import { useCallback, useEffect, useRef, useState } from "react";

export type AsyncStatus = "idle" | "pending" | "success" | "error";

export type AsyncState<TData, TError> =
  | {
      status: "idle";
      data: undefined;
      error: undefined;
      isIdle: true;
      isLoading: false;
      isSuccess: false;
      isError: false;
    }
  | {
      status: "pending";
      data: TData | undefined; // preserves previous data while refetching
      error: undefined;
      isIdle: false;
      isLoading: true;
      isSuccess: false;
      isError: false;
    }
  | {
      status: "success";
      data: TData;
      error: undefined;
      isIdle: false;
      isLoading: false;
      isSuccess: true;
      isError: false;
    }
  | {
      status: "error";
      data: undefined;
      error: TError;
      isIdle: false;
      isLoading: false;
      isSuccess: false;
      isError: true;
    };

export type UseAsyncOptions<TData, TError, TArgs extends unknown[]> = {
  action: (...args: TArgs) => Promise<TData> | TData;
  onSuccess?: (data: TData, args: TArgs) => void;
  onError?: (error: TError, args: TArgs) => void;
  onSettled?: (
    data: TData | undefined,
    error: TError | undefined,
    args: TArgs,
  ) => void;
};

export type UseAsyncReturn<TData, TError, TArgs extends unknown[]> = AsyncState<
  TData,
  TError
> & {
  execute: (...args: TArgs) => Promise<TData>;
  reset: () => void;
};

const IDLE_STATE = {
  status: "idle",
  data: undefined,
  error: undefined,
  isIdle: true,
  isLoading: false,
  isSuccess: false,
  isError: false,
} as const;

export function useAsync<
  TData = unknown,
  TError = unknown,
  TArgs extends unknown[] = [],
>(
  options: UseAsyncOptions<TData, TError, TArgs>,
): UseAsyncReturn<TData, TError, TArgs> {
  const [state, setState] = useState<AsyncState<TData, TError>>(IDLE_STATE);

  // always fresh callbacks without forcing execute to change identity (deps array)
  const optionsRef = useRef(options);
  useEffect(() => {
    optionsRef.current = options;
  });

  // latest wins , stale response will dropped
  const requestIdRef = useRef(0);

  // prevent setState after mounted
  const mountedRef = useRef(true);
  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
    };
  }, []);

  const execute = useCallback(async (...args: TArgs): Promise<TData> => {
    // Tăng trước khi đọc
    const requestId = ++requestIdRef.current;
    const { action, onSuccess, onError, onSettled } = optionsRef.current;
    setState((prev) => ({
      status: "pending",
      data: prev.data,
      error: undefined,
      isIdle: false,
      isLoading: true,
      isSuccess: false,
      isError: false,
    }));
    try {
      const data = await action(...args);
      if (requestId === requestIdRef.current && mountedRef.current) {
        // commit state only on the latest && component still mounted
        setState({
          status: "success",
          data,
          error: undefined,
          isIdle: false,
          isLoading: false,
          isSuccess: true,
          isError: false,
        });
        onSuccess?.(data, args);
        onSettled?.(data, undefined, args);
      }

      return data;
    } catch (err) {
      const error = err as TError;
      if (requestId === requestIdRef.current && mountedRef.current) {
        setState({
          status: "error",
          data: undefined,
          error,
          isIdle: false,
          isLoading: false,
          isSuccess: false,
          isError: true,
        });
        onError?.(error, args);
        onSettled?.(undefined, error, args);
      }
      throw err;
    }
  }, []);

  const reset = useCallback(() => {
    requestIdRef.current++;
    if (mountedRef.current) {
      setState(IDLE_STATE);
    }
  }, []);

  return { ...state, execute, reset };
}
